using System;
using System.Collections.Generic;
using UnityEngine;
public static class GridShiftSaveValidation {
 public static bool ValidDepot(DeliveryOrder o){if(!Finite(o.personalDrivenMeters)||o.personalDrivenMeters<0||!Finite(o.depotAutomationRemaining)||o.depotAutomationRemaining<0||o.depotAutomationRemaining>3600||o.depotZone<0||o.depotZone>1)return false;if(!o.depotRequired)return !o.depotScanned&&!o.depotPacked&&!o.depotLabelled&&!o.depotSorted&&!o.depotReleased&&o.depotAutomationRemaining==0;return o.mode==DeliveryMode.Personal&&(!o.depotPacked||o.depotScanned)&&(!o.depotLabelled||o.depotPacked)&&(!o.depotSorted||o.depotLabelled)&&(!o.depotReleased||o.depotSorted);}
 public static bool ValidVan(DeliverySaveData data){var v=data.personalVan;if(v==null)return true;if(!Position(v.position)||!Position(v.safeExit)||!Rotation(v.rotation)||(v.hasSafePosition&&(!Position(v.safePosition)||!Rotation(v.safeRotation))))return false;if(string.IsNullOrEmpty(v.cargoOrderId))return true;return data.orders!=null&&data.orders.Exists(o=>o!=null&&o.id==v.cargoOrderId&&o.mode==DeliveryMode.Personal&&o.status==DeliveryStatus.Transporting);}
 public static bool ValidOrder(DeliveryOrder order){return order!=null&&ValidDepot(order)&&(!order.rewardPaid||order.status==DeliveryStatus.Completed)&&order.courierPhase>=0&&order.courierPhase<=5&&(!order.courierInitialized||(order.courierNode>=0&&Position(order.courierPosition)))&&!double.IsNaN(order.completedDay)&&!double.IsInfinity(order.completedDay)&&order.completedDay>=0;}
 static bool Finite(float v)=>!float.IsNaN(v)&&!float.IsInfinity(v);static bool Rotation(Quaternion q)=>Finite(q.x)&&Finite(q.y)&&Finite(q.z)&&Finite(q.w)&&Quaternion.Dot(q,q)>.001f;static bool Position(Vector3 p)=>Finite(p.x)&&Finite(p.y)&&Finite(p.z)&&p.sqrMagnitude<1e12f;
 public static bool Valid(DeliverySaveData d){if(d.version>=6&&d.tutorial!=null&&(!Finite(d.tutorial.walked)||!Finite(d.tutorial.ran)||!Finite(d.tutorial.looked)||d.tutorial.step<0||d.tutorial.step>15))return false;if(!ValidVan(d)||d.slot<0||d.slot>5||double.IsNaN(d.playSeconds)||double.IsInfinity(d.playSeconds)||d.playSeconds<0||d.playSeconds>3155760000||!Position(d.activePlayerPosition)||!Rotation(d.activePlayerRotation)||d.vehicles==null||d.vehicles.Count>32||(d.currentScene!="SampleScene"&&d.currentScene!="Office"&&d.currentScene!="Apartment"&&d.currentScene!="FactoryInterior"))return false;var ids=new HashSet<string>();foreach(var v in d.vehicles)if(v==null||string.IsNullOrEmpty(v.id)||!ids.Add(v.id)||!Enum.IsDefined(typeof(FleetKind),v.kind)||!Enum.IsDefined(typeof(FleetStatus),v.state)||!Position(v.position)||!Rotation(v.rotation)||!Finite(v.capacityKg)||v.capacityKg<=0||!Finite(v.serviceRemaining)||v.serviceRemaining<0||v.nextPoint<1)return false;return true;}
}



